M.Register({
	class = "WARRIOR", url = "https://classicwowforever.com/macros/warrior/",
	specs = { { key = "arms", name = L["Arms"] }, { key = "fury", name = L["Fury"] }, { key = "protection", name = L["Protection"] } },
	-- { id, spec (nil: the whole class), pvp, origin, level, icon, code, title, use, needs, keys = { { modifier, what it does } }, fill }
	macros = {
		{ id = "class-wide-charge", pvp = false, origin = "adapted", icon = "ability_warrior_charge",
			code = "#showtooltip {s100}\n/dismount\n/startattack\n/cast {s100}",
			title = L["Charge and start attacking"],
			use = L["Get off your mount, start swinging and Charge in one press."],
			needs = L["Battle Stance (Defensive Stance with Vanguard); out of combat"] },
		{ id = "class-wide-charge-or-intercept", pvp = false, origin = "classic", level = 30, icon = "classicon_warrior",
			code = "#show [combat] {s20252}; {s100}\n/startattack\n/cast [nocombat,stance:1] {s100}; [combat,stance:3] {s20252}; [nocombat,nostance:1] {s2457}; [combat,nostance:3] {s2458}",
			title = L["Charge out of combat, Intercept in it"],
			use = L["Charge from Battle Stance out of combat and Intercept from Berserker Stance in combat. If you're in the wrong stance the press swaps first, then press again."],
			needs = L["Charge and Intercept learned"] },
		{ id = "class-wide-victory-rush", pvp = false, origin = "forever", icon = "ability_warrior_devastate",
			code = "#showtooltip {s402927}\n/startattack\n/cast {s402927}",
			title = L["Victory Rush after a kill"],
			use = L["Use the new follow-up strike within 20 seconds of defeating a non-trivial enemy; it also heals you for 10% of your maximum health."],
			needs = L["Victory Rush learned; a qualifying recent kill"] },
		{ id = "class-wide-berserker-rage", pvp = false, origin = "classic", level = 30, icon = "spell_nature_ancestralguardian",
			code = "#showtooltip {s18499}\n/cast [nostance:3] {s2458}\n/cast {s18499}",
			title = L["Berserker Rage with a stance swap"],
			use = L["Swap into Berserker Stance if you aren't in it and use Berserker Rage, which makes you immune to Fear and Incapacitate for 10 sec."],
			needs = L["Berserker Stance. Learned at 30"] },
		{ id = "class-wide-execute", pvp = false, origin = "classic", level = 24, icon = "inv_sword_48",
			code = "#showtooltip {s5308}\n/startattack\n/cast [stance:2] {s2457}\n/cast [mod:shift,@mouseover,harm,nodead] {s5308}; {s5308}",
			title = L["Execute your target or mouseover"],
			use = L["Start attacking and Execute a target under 20% health, or your mouseover with Shift. From Defensive Stance it swaps to Battle Stance first."],
			needs = L["Battle or Berserker Stance; target under 20% health"],
			keys = { { false, L["Execute your target"] }, { "Shift", L["Execute your mouseover instead"] } } },
		{ id = "class-wide-heroic-strike-cleave", pvp = false, origin = "classic", icon = "ability_rogue_ambush",
			code = "#showtooltip [mod:shift] {s845}; {s78}\n/startattack\n/cast [mod:shift] {s845}; {s78}",
			title = L["Heroic Strike or Cleave"],
			use = L["Start attacking and queue Heroic Strike on your next swing, or Cleave with Shift when a second enemy is close by."],
			keys = { { false, L["Queue Heroic Strike on your next swing"] }, { "Shift", L["Queue Cleave instead"] } } },
		{ id = "class-wide-trinkets", pvp = false, origin = "classic", icon = "classicon_warrior",
			code = "#showtooltip\n/use 13\n/use 14",
			title = L["Use both trinkets"],
			use = L["Use your top and bottom trinkets together."],
			needs = L["Trinkets equipped in both slots"] },
		{ id = "class-wide-bloodrage-rage-potion", pvp = false, origin = "classic", icon = "ability_racial_bloodrage",
			code = "#showtooltip {s2687}\n/cast {s2687}\n/use {i5631}",
			title = L["Bloodrage and a Rage Potion"],
			use = L["Bloodrage and a Rage Potion together, so the potion's 20 to 40 Rage lands on top of Bloodrage's."],
			needs = L["Rage Potion in your bags (an Alchemy craft)"] },
		{ id = "class-wide-shout-picker", pvp = false, origin = "classic", icon = "ability_warrior_battleshout",
			code = "#showtooltip [mod:shift] {s1160}; {s5242}\n/cast [mod:shift] {s1160}; {s5242}",
			title = L["Battle Shout, Shift for Demoralizing Shout"],
			use = L["Refresh Battle Shout, or hold Shift to weaken nearby enemies with Demoralizing Shout. You choose which shout to spend Rage on."],
			needs = L["Both shouts learned"],
			keys = { { false, L["Battle Shout"] }, { "Shift", L["Demoralizing Shout"] } } },
		{ id = "pvp-interrupt", pvp = true, origin = "classic", level = 38, icon = "classicon_warrior",
			code = "#showtooltip\n/stopcasting\n/cast [mod:shift,@mouseover,harm,nodead,equipped:Shields,stance:1/2] {s72}; [mod:shift,@mouseover,harm,nodead,stance:3] {s6552}; [equipped:Shields,stance:1/2] {s72}; [stance:3] {s6552}; {s2458}",
			title = L["One-button interrupt"],
			use = L["Shield Bash with a shield in Battle or Defensive Stance, Pummel in Berserker Stance. Without a shield it swaps you to Berserker Stance first. It also stops your own Slam."],
			needs = L["Shield Bash and Pummel learned"],
			keys = { { false, L["Interrupt your target"] }, { "Shift", L["Interrupt your mouseover instead"] } } },
		{ id = "pvp-intercept", pvp = true, origin = "classic", level = 30, icon = "ability_rogue_sprint",
			code = "#showtooltip {s20252}\n/cast [nostance:3] {s2458}\n/cast [mod:shift,@mouseover,harm,nodead] {s20252}; {s20252}",
			title = L["Intercept your target or mouseover"],
			use = L["Swap to Berserker Stance if needed and Intercept for a 3 sec stun. Hold Shift to pick your mouseover."],
