			needs = L["Missile Barrage talent. A cast you started less than 1.5 sec ago still holds the global cooldown, so the Missiles wait for it."] },
		{ id = "pvp-arcane-wrath-opener", spec = "arcane", pvp = true, origin = "forever", level = 25, icon = "spell_arcane_blast",
			code = "#showtooltip [nocombat] {s1326079}; {s400574}\n/cast [nocombat] {s1326079}; {s400574}",
			title = L["Arcane Wrath to open, Arcane Blast after"],
