			title = L["Frostbolt to slow, Cone of Cold when they close"],
			use = L["Frostbolts the enemy under your cursor, or your target. Shift casts rank 1, a 1.5 sec cast with a shorter slow. Ctrl drops your cast for Cone of Cold, which your Winter’s Chill stacks make hit harder."],
			needs = L["Cone of Cold (26) for Ctrl"],
			keys = { { false, L["Frostbolt your mouseover, or your target"] }, { "Shift", L["Frostbolt rank 1 on the same enemy"] }, { "Ctrl", L["Stop casting, then Cone of Cold"] } } },
