M.Register({
	class = "WARLOCK", url = "https://classicwowforever.com/macros/warlock/",
	specs = { { key = "affliction", name = L["Affliction"] }, { key = "demonology", name = L["Demonology"] }, { key = "destruction", name = L["Destruction"] } },
	-- { id, spec (nil: the whole class), pvp, origin, level, icon, code, title, use, needs, keys = { { modifier, what it does } }, fill }
	macros = {
