			needs = L["Each curse learned (Elements at 20, Tongues at 26). Blizzard removed Curse of Shadow, and Curse of the Elements now covers every magic school"],
			keys = { { false, L["Curse of the Elements"] }, { "Shift", L["Curse of Weakness"] }, { "Ctrl", L["Curse of Recklessness"] }, { "Alt", L["Curse of Tongues on your target"] } } },
