			code = "#showtooltip\n/use [@mouseover,help,nodead][] {i16896}\n/use [@mouseover,help,nodead][] {i16895}\n/use [@mouseover,help,nodead][] {i16893}\n/use [@mouseover,help,nodead][] {i16892}\n/use [@mouseover,help,nodead][] {i5232}",
			title = L["Soulstone your mouseover or target"],
			use = L["Use your Soulstone on the friendly player under your cursor, or on your target if nothing's hovered."],
			needs = L["A Soulstone in your bags (Create Soulstone at 18)"] },
